def solve(n, edges, s, t):
    """
    Finds the shortest path from a start node to a target node in a directed
    weighted graph.

    Args:
        n: The number of nodes in the graph (numbered 0 to n-1).
        edges: A list of (u, v, w) tuples, where u is the source node,
               v is the destination node, and w is the weight of the edge.
        s: The starting node.
        t: The target node.

    Returns:
        The minimum total weight of a path from s to t, or 0 if s == t,
        or -1 if t cannot be reached from s.
    """

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    if s == t:
        return 0

    dist = {i: float('inf') for i in range(n)}
    dist[s] = 0
    queue = deque([(s, 0)])  # (node, distance)

    while queue:
        u, d = queue.popleft()

        if d > dist[u]:
            continue

        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append((v, dist[v]))

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]

