                if compressed_nums[mid] < num:
                    l = mid + 1
                else:
                    r = mid - 1
            compressed_nums[l] = num

    n = len(compressed_nums)
    fenwick_tree = [0] * (n + 1)

    def update(i, val):
        i += 1
        while i <= n:
            fenwick_tree[i] = max(fenwick_tree[i], val)
            i += i & -i

    def query(i):
        i += 1
        res = 0
        while i > 0:
            res = max(res, fenwick_tree[i])
            i -= i & -i
        return res

    for i, num in enumerate(compressed_nums):
        length = query(i) + 1
        update(i, length)

    return query(n - 1)

